335	  // ---------- данные для текущего выбора ----------
336	  function combo(period, variant) {
337	    const acc = (D.account[period] || {})[variant] || null;
338	    const kpi = (D.kpi[period] || {})[variant] || null;
339	    const trades = ((D.trades[period] || {})[variant]) || [];
340	    return {acc, kpi, trades};
341	  }
342	  function sharpeSortino(dailyUsd, depositUsd) {
343	    const vals = Object.values(dailyUsd || {}).map(v => v / depositUsd * 100);
344	    if (vals.length < 2) return [null, null];
345	    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
346	    const std = Math.sqrt(vals.reduce((a, b) => a + (b - mean) ** 2, 0) / vals.length);
347	    const down = vals.filter(v => v < 0);
348	    let dstd = 0;
349	    if (down.length >= 2) { const dm2 = down.reduce((a, b) => a + b, 0) / down.length; dstd = Math.sqrt(down.reduce((a, b) => a + (b - dm2) ** 2, 0) / down.length); }
350	    else if (down.length === 1) dstd = Math.abs(down[0]);
351	    const ann = Math.sqrt(365);
352	    return [std > 0 ? mean / std * ann : null, dstd > 0 ? mean / dstd * ann : null];
353	  }
354	  function dailySeriesFor(period, variant) {
355	    const {acc, kpi} = combo(period, variant);
356	    return acc ? acc.daily_usd : (kpi ? kpi.daily_usd : {});
357	  }
