365	    const n = acc ? acc.n : kpi.n;
366	    const netUsd = acc ? acc.net_usd : kpi.net_usd;
367	    const netPct = acc ? acc.net_pct : (netUsd / D.deposit_usd * 100);
368	    const ddPct = acc ? acc.dd_pct : kpi.dd_pct_trade;
369	    const rf = acc ? acc.recovery_factor : (kpi.dd_usd_trade ? +( -netUsd === 0 ? 0 : netUsd / Math.abs(kpi.dd_usd_trade)).toFixed(2) : null);
370	    const win = acc ? acc.win_rate : kpi.win_rate;
371	    const peakN = acc ? acc.peak_n : kpi.peak_n;
372	    const peakUsd = acc ? acc.peak_usd : kpi.peak_usd;
373	    let sharpe, sortino;
374	    if (acc) { sharpe = acc.sharpe; sortino = acc.sortino; } else { [sharpe, sortino] = sharpeSortino(kpi.daily_usd, D.deposit_usd); }
375	    const tiles = [
376	      ["Чистая прибыль", money(netUsd), null, cls(netUsd), "Сумма результата всех сделок в долларах на реальном размере позиции."],
377	      ["Доходность", pctFmt(netPct), "от депозита $" + intFmt(D.deposit_usd), cls(netPct), "Чистая прибыль, делённая на депозит счёта."],
378	      ["Просадка", "−" + pctPlain(ddPct), "макс. по счёту", "neg", "Самый глубокий откат капитала от предыдущего пика, в % депозита."],
379	      ["Фактор восстановления", rf == null ? "—" : rf.toFixed(2), null, cls(rf != null ? rf - 1 : null), "Чистая прибыль, делённая на максимальную просадку: сколько просадок «уложилось» в итог."],
380	      ["Шарп", sharpe == null ? "—" : sharpe.toFixed(2), "по дням, годовых", cls(sharpe), "Средняя дневная доходность к её разбросу, приведено к году (√365)."],
