426	  function dateTicks(o, from, to) {
427	    const span = (Date.parse(to) - Date.parse(from)) / 86400e3;
428	    const step = Math.max(1, Math.round(span / 8)) * 86400e3;
429	    o.scales.x.type = "linear"; o.scales.x.min = Date.parse(from + "T00:00:00Z"); o.scales.x.max = Date.parse(to + "T00:00:00Z") + 86400e3;
430	    o.scales.x.ticks.stepSize = step;
431	    o.scales.x.ticks.callback = v => dm(new Date(v).toISOString().slice(0, 10));
